# mandelbrot.py
import time

def generate_mandelbrot(width, height, max_iter):
    # Image dimensions and scale
    x_min, x_max = -2.0, 0.5
    y_min, y_max = -1.25, 1.25

    # Pre-calculate scales
    x_scale = (x_max - x_min) / width
    y_scale = (y_max - y_min) / height

    image = []

    for py in range(height):
        row = []
        y0 = y_min + py * y_scale
        for px in range(width):
            x0 = x_min + px * x_scale
            x, y = 0.0, 0.0
            iteration = 0

            # The core loop: where the performance difference happens
            while x*x + y*y <= 4 and iteration < max_iter:
                xtemp = x*x - y*y + x0
                y = 2*x*y + y0
                x = xtemp
                iteration += 1

            row.append(iteration)
        image.append(row)
    return image

def save_pgm(data, filename):
    width = len(data[0])
    height = len(data)
    max_val = 255
    with open(filename, 'wb') as f:
        f.write(f"P2\n{width} {height}\n{max_val}\n".encode())
        for row in data:
            for pixel in row:
                # Normalize the iterations to 0-255
                val = min(pixel, max_val)
                f.write(f"{val} ".encode())
            f.write(b"\n")

if __name__ == "__main__":
    W, H, ITER = 1000, 1000, 100
    start = time.time()
    result = generate_mandelbrot(W, H, ITER)
    end = time.time()
    save_pgm(result, "mandelbrot_py.pgm")
    print(f"Python execution time: {end - start:.4f} seconds")
