import numpy as np
import time

def mandelbrot(h, w, max_iter=100):
    # Create a grid of complex numbers
    y, x = np.ogrid[-1.5:1.5:h*1j, -2:1:w*1j]
    c = x + y*1j
    z = c
    divtime = max_iter + np.zeros(z.shape, dtype=int)

    for i in range(max_iter):
        z = z**2 + c
        diverge = z*np.conj(z) > 2**2            # find points that diverge
        div_now = diverge & (divtime == max_iter)  # find points diverging right now
        divtime[div_now] = i                    # note time of divergence
        z[diverge] = 2                          # prevent overflow

    return divtime

if __name__ == "__main__":
