        let temp = zx * zx - zy * zy + cx;
        zy = 2.0 * zx * zy + cy;
        zx = temp;
    }
    max_iter
}

fn main() {
    let width = 1000;
    let height = 1000;
    let max_iter = 100;
    let x_min = -2.0;
    let x_max = 0.5;
    let y_min = -1.25;
    let y_max = 1.25;

    let start = Instant::now();

    // .into_par_iter() is the magic of Rayon: it distributes the work across all CPU cores
    let _result: Vec<Vec<u32>> = (0..height).into_par_iter().map(|py| {
        let mut row = Vec::with_capacity(width);
        for px in 0..width {
            let x0 = x_min + (px as f64 / width as f64) * (x_max - x_min);
            let y0 = y_min + (py as f64 / height as f64) * (y_max - y_min);
            row.push(mandelbrot(x0, y0, max_iter));
        }
        row
    }).collect();

    println!("Rust took: {:.4?} seconds", start.elapsed());
}
